//! Color conversions, pyDatView color cycles, and canonical Matplotlib colormaps.
use dv_core::error::{DvError, Result};
pub type Rgb = [f64; 3];
pub type Rgba = [f64; 4];
pub const fn rgb(r: f64, g: f64, b: f64) -> Rgb {
    if r + g + b <= 3.0 {
        [r, g, b]
    } else {
        [r / 255.0, g / 255.0, b / 255.0]
    }
}
pub fn standardize(color: Rgb) -> Rgb {
    if color.iter().any(|v| *v > 1.0) {
        color.map(|v| v / 255.0)
    } else {
        color
    }
}
pub fn hex2rgb(hex: &str) -> Result<Rgb> {
    let hex = hex.strip_prefix('#').unwrap_or(hex);
    if hex.len() != 6 || !hex.is_ascii() {
        return Err(DvError::msg(
            "RGB hex colors require six hexadecimal digits",
        ));
    }
    let mut color = [0.0; 3];
    for i in 0..3 {
        color[i] = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16)
            .map_err(|_| DvError::msg("Invalid RGB hex color"))? as f64
            / 255.0;
    }
    Ok(color)
}
pub fn rgb2hex(color: Rgb) -> String {
    let c = standardize(color).map(|v| (v.clamp(0.0, 1.0) * 255.0).round() as u8);
    format!("#{:02X}{:02X}{:02X}", c[0], c[1], c[2])
}
pub fn rgb_to_hls([r, g, b]: Rgb) -> Rgb {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;
    let d = max - min;
    if d == 0.0 {
        return [0.0, l, 0.0];
    }
    let s = if l <= 0.5 {
        d / (max + min)
    } else {
        d / (2.0 - max - min)
    };
    let h = if r == max {
        (g - b) / d
    } else if g == max {
        2.0 + (b - r) / d
    } else {
        4.0 + (r - g) / d
    };
    [(h / 6.0).rem_euclid(1.0), l, s]
}
pub fn hls_to_rgb([h, l, s]: Rgb) -> Rgb {
    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
    let hp = h.rem_euclid(1.0) * 6.0;
    let x = c * (1.0 - (hp.rem_euclid(2.0) - 1.0).abs());
    let m = l - c / 2.0;
    let rgb = match hp as usize {
        0 => [c, x, 0.0],
        1 => [x, c, 0.0],
        2 => [0.0, c, x],
        3 => [0.0, x, c],
        4 => [x, 0.0, c],
        _ => [c, 0.0, x],
    };
    rgb.map(|v| v + m)
}
pub fn adjust_color_lightness(color: Rgb, factor: f64) -> Rgb {
    let mut hls = rgb_to_hls(color);
    hls[1] = (hls[1] * factor).clamp(0.0, 1.0);
    hls_to_rgb(hls)
}
pub fn lighten_color(color: Rgb, factor: f64) -> Rgb {
    adjust_color_lightness(standardize(color), 1.0 + factor)
}
pub fn darken_color(color: Rgb, factor: f64) -> Rgb {
    adjust_color_lightness(standardize(color), 1.0 - factor)
}
