/// Upstream's one-based color index; optional count selects a black-to-gray cycle.
pub fn fcolrs(i: usize, n: Option<usize>, black_and_white: bool) -> Rgb {
    if let Some(n) = n {
        if black_and_white {
            let v = if n <= 1 {
                0.0
            } else {
                0.55 * i.saturating_sub(1) as f64 / (n - 1) as f64
            };
            return [v; 3];
        }
    }
    FCOLRS[i.wrapping_sub(1) % FCOLRS.len()]
}
pub fn fgray(value: f64) -> Rgb {
    [value; 3]
}
#[derive(Debug, Clone)]
pub struct ColorMap {
    pub name: String,
    colors: Vec<Rgba>,
    values: Vec<f64>,
}
impl ColorMap {
    pub fn sample(&self, value: f64) -> Rgba {
        let value = if value.is_nan() {
            return [0.0; 4];
        } else {
            value.clamp(0.0, 1.0)
        };
        // Matplotlib's LinearSegmentedColormap uses a 256-entry lookup table.
        let value = ((value * 256.0).floor().min(255.0)) / 255.0;
        let i = self
            .values
            .partition_point(|v| *v <= value)
            .saturating_sub(1)
            .min(self.colors.len() - 2);
        let f = (value - self.values[i]) / (self.values[i + 1] - self.values[i]);
        std::array::from_fn(|c| self.colors[i][c] + f * (self.colors[i + 1][c] - self.colors[i][c]))
    }
    pub fn colors(&self, n: usize) -> Vec<Rgba> {
        (0..n)
            .map(|i| {
                self.sample(if n <= 1 {
                    0.0
                } else {
                    i as f64 / (n - 1) as f64
                })
            })
            .collect()
    }
}
pub fn make_colormap(seq: &[Rgb], values: Option<&[f64]>, name: &str) -> Result<ColorMap> {
    let rgba: Vec<_> = seq.iter().map(|c| [c[0], c[1], c[2], 1.0]).collect();
    make_colormap_rgba(&rgba, values, name)
}
pub fn make_colormap_rgba(seq: &[Rgba], values: Option<&[f64]>, name: &str) -> Result<ColorMap> {
    if seq.len() < 2
        || seq
            .iter()
            .flatten()
            .any(|v| !v.is_finite() || *v < 0.0 || *v > 1.0)
    {
        return Err(DvError::msg(
            "Colormap requires at least two normalized RGB(A) colors",
        ));
    }
    let values = values.map(|v| v.to_vec()).unwrap_or_else(|| {
        (0..seq.len())
            .map(|i| i as f64 / (seq.len() - 1) as f64)
            .collect()
    });
    if values.len() != seq.len()
        || values[0] != 0.0
        || values[values.len() - 1] != 1.0
        || values.iter().any(|v| !v.is_finite())
        || values.windows(2).any(|p| p[0] >= p[1])
    {
        return Err(DvError::msg(
            "Colormap positions must increase from zero to one and match colors",
        ));
    }
    Ok(ColorMap {
        name: name.into(),
        colors: seq.to_vec(),
        values,
    })
}
pub fn cmap_colors(n: usize, name: &str) -> Result<Vec<Rgb>> {
    let (map, reverse) = named_map(name)?;
    Ok((0..n)
        .map(|i| {
            let v = if n <= 1 {
                0.0
            } else {
                i as f64 / (n - 1) as f64
            };
            sample_named(map, v, reverse)
        })
        .collect())
}
pub fn color_scales(n: usize, color: &str) -> Result<Vec<Rgba>> {
    let name = match color {
        "blue" => "Blues",
        "purple" => "Purples",
        "orange" => "Oranges",
        "red" => "Reds",
        "green" => "Greens",
        "gray" | "grey" => "Greys",
        _ => return Err(DvError::msg(format!("Unknown color scale: {color}"))),
    };
    let (map, reverse) = named_map(name)?;
    Ok((0..n)
        .rev()
        .map(|i| {
            let c = sample_named(map, i as f64 / n as f64, reverse);
            [c[0], c[1], c[2], 1.0]
        })
        .collect())
}
fn sample_named(map: &[Rgb], v: f64, reverse: bool) -> Rgb {
    let i = ((v.clamp(0.0, 1.0) * map.len() as f64).floor() as usize).min(map.len() - 1);
    map[if reverse { map.len() - 1 - i } else { i }]
}
// Canonical map tables and registry follow below.
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn hls_roundtrip() {
        for c in [
            [0., 0., 0.],
            [1., 1., 1.],
            [0.3, 0.5, 0.4],
            [0.1, 0.9, 0.9],
            [0.9, 0.1, 0.9],
        ] {
            let out = hls_to_rgb(rgb_to_hls(c));
            for (a, b) in out.iter().zip(c) {
                assert!((a - b).abs() < 1e-12);
            }
        }
    }
    #[test]
    fn hex_and_cycle() {
        assert_eq!(rgb2hex(hex2rgb("#1F77B4").unwrap()), "#1F77B4");
        assert_eq!(python_color(10), python_color(0));
    }
    #[test]
    fn canonical_maps() {
        let c = cmap_colors(2, "viridis").unwrap();
        assert_eq!(c[0], [0.267004, 0.004874, 0.329415]);
        assert_eq!(c[1], [0.993248, 0.906157, 0.143936]);
        assert!(cmap_colors(2, "unknown").is_err());
    }
}

fn named_map(name: &str) -> Result<(&'static [Rgb], bool)> {
    let (name, reverse) = name
        .strip_suffix("_r")
        .map(|s| (s, true))
        .unwrap_or((name, false));
    let map: &[Rgb] = match name {
        "Accent" => &MAP_ACCENT,
        "Blues" => &MAP_BLUES,
        "BrBG" => &MAP_BRBG,
        "BuGn" => &MAP_BUGN,
        "BuPu" => &MAP_BUPU,
        "CMRmap" => &MAP_CMRMAP,
        "Dark2" => &MAP_DARK2,
        "GnBu" => &MAP_GNBU,
        "Greens" => &MAP_GREENS,
        "Greys" => &MAP_GREYS,
        "OrRd" => &MAP_ORRD,
        "Oranges" => &MAP_ORANGES,
        "PRGn" => &MAP_PRGN,
        "Paired" => &MAP_PAIRED,
        "Pastel1" => &MAP_PASTEL1,
        "Pastel2" => &MAP_PASTEL2,
        "PiYG" => &MAP_PIYG,
        "PuBu" => &MAP_PUBU,
        "PuBuGn" => &MAP_PUBUGN,
        "PuOr" => &MAP_PUOR,
        "PuRd" => &MAP_PURD,
        "Purples" => &MAP_PURPLES,
        "RdBu" => &MAP_RDBU,
        "RdGy" => &MAP_RDGY,
        "RdPu" => &MAP_RDPU,
        "RdYlBu" => &MAP_RDYLBU,
        "RdYlGn" => &MAP_RDYLGN,
        "Reds" => &MAP_REDS,
        "Set1" => &MAP_SET1,
        "Set2" => &MAP_SET2,
        "Set3" => &MAP_SET3,
        "Spectral" => &MAP_SPECTRAL,
        "Wistia" => &MAP_WISTIA,
        "YlGn" => &MAP_YLGN,
        "YlGnBu" => &MAP_YLGNBU,
        "YlOrBr" => &MAP_YLORBR,
        "YlOrRd" => &MAP_YLORRD,
        "afmhot" => &MAP_AFMHOT,
        "autumn" => &MAP_AUTUMN,
        "binary" => &MAP_BINARY,
        "bone" => &MAP_BONE,
        "brg" => &MAP_BRG,
        "bwr" => &MAP_BWR,
        "cividis" => &MAP_CIVIDIS,
        "cool" => &MAP_COOL,
        "coolwarm" => &MAP_COOLWARM,
        "copper" => &MAP_COPPER,
        "cubehelix" => &MAP_CUBEHELIX,
        "flag" => &MAP_FLAG,
        "gist_earth" => &MAP_GIST_EARTH,
        "gist_gray" => &MAP_GIST_GRAY,
        "gist_heat" => &MAP_GIST_HEAT,
        "gist_ncar" => &MAP_GIST_NCAR,
        "gist_rainbow" => &MAP_GIST_RAINBOW,
        "gist_stern" => &MAP_GIST_STERN,
        "gist_yarg" => &MAP_GIST_YARG,
        "gnuplot" => &MAP_GNUPLOT,
        "gnuplot2" => &MAP_GNUPLOT2,
        "gray" => &MAP_GRAY,
        "hot" => &MAP_HOT,
        "hsv" => &MAP_HSV,
        "inferno" => &MAP_INFERNO,
        "jet" => &MAP_JET,
        "magma" => &MAP_MAGMA,
        "nipy_spectral" => &MAP_NIPY_SPECTRAL,
        "ocean" => &MAP_OCEAN,
        "pink" => &MAP_PINK,
        "plasma" => &MAP_PLASMA,
        "prism" => &MAP_PRISM,
        "rainbow" => &MAP_RAINBOW,
        "seismic" => &MAP_SEISMIC,
        "spring" => &MAP_SPRING,
        "summer" => &MAP_SUMMER,
        "tab10" => &MAP_TAB10,
        "tab20" => &MAP_TAB20,
        "tab20b" => &MAP_TAB20B,
        "tab20c" => &MAP_TAB20C,
        "terrain" => &MAP_TERRAIN,
        "turbo" => &MAP_TURBO,
        "twilight" => &MAP_TWILIGHT,
        "twilight_shifted" => &MAP_TWILIGHT_SHIFTED,
        "viridis" => &MAP_VIRIDIS,
        "winter" => &MAP_WINTER,
        _ => return Err(DvError::msg(format!("Unknown colormap: {name}"))),
    };
    Ok((map, reverse))
}

